Q = {}
def add(key, question=None, step_overrides=None, **fields):
    iid = f"ch07.q.{key}"
    if question: Q[f"{iid}.question"] = question
    if step_overrides is not None: Q[f"{iid}.answer_steps"] = steps(iid, step_overrides)
    for f, v in fields.items(): Q[f"{iid}.{f}"] = v

