Q["ch07.q.ex7_2.q3.figure.title"] = ("हरा झंडा (G) और लाल झंडा (R)", "લીલી ધજા (G) અને લાલ ધજા (R)")
add("ex7_2.q4", ("बिंदुओं $(-3, 10)$ और $(6, -8)$ को मिलाने वाले रेखाखंड को बिंदु $(-1, 6)$ किस अनुपात में विभाजित करता है?", "બિંદુઓ $(-3, 10)$ અને $(6, -8)$ ને જોડતા રેખાખંડનું બિંદુ $(-1, 6)$ કયા ગુણોત્તરમાં વિભાજન કરે છે?"),
    {0: ("मान लीजिए अनुपात $k : 1$ है: $\\dfrac{6k - 3}{k + 1} = -1$।", "ધારો કે ગુણોત્તર $k : 1$ છે: $\\dfrac{6k - 3}{k + 1} = -1$."), 2: ("अनुपात $2 : 7$ है।", "ગુણોત્તર $2 : 7$ છે.")})
add("ex7_2.q5", ("वह अनुपात ज्ञात कीजिए जिसमें $A(1, -5)$ और $B(-4, 5)$ को मिलाने वाला रेखाखंड $x$-अक्ष से विभाजित होता है। इस विभाजन बिंदु के निर्देशांक भी ज्ञात कीजिए।", "$A(1, -5)$ અને $B(-4, 5)$ ને જોડતા રેખાખંડનું $x$-અક્ષ વડે કયા ગુણોત્તરમાં વિભાજન થાય છે તે શોધો. વિભાજન બિંદુના યામ પણ શોધો."),
    {0: ("मान लीजिए अनुपात $k : 1$ है। $x$-अक्ष पर $y = 0$: $\\dfrac{5k - 5}{k + 1} = 0$, अतः $k = 1$।", "ધારો કે ગુણોત્તર $k : 1$ છે. $x$-અક્ષ પર $y = 0$: $\\dfrac{5k - 5}{k + 1} = 0$, તેથી $k = 1$."),
     1: ("अनुपात $1 : 1$ है (बिंदु मध्य-बिंदु है)।", "ગુણોત્તર $1 : 1$ છે (બિંદુ મધ્યબિંદુ છે)."), 2: ("बिंदु $= \\left(\\dfrac{1 - 4}{2}, 0\\right) = \\left(-\\dfrac{3}{2}, 0\\right)$", "બિંદુ $= \\left(\\dfrac{1 - 4}{2}, 0\\right) = \\left(-\\dfrac{3}{2}, 0\\right)$")})
add("ex7_2.q6", ("यदि $(1, 2)$, $(4, y)$, $(x, 6)$ और $(3, 5)$ इसी क्रम में लिए गए एक समांतर चतुर्भुज के शीर्ष हैं, तो $x$ और $y$ ज्ञात कीजिए।", "જો $(1, 2)$, $(4, y)$, $(x, 6)$ અને $(3, 5)$ આ ક્રમમાં લીધેલાં સમાંતરબાજુ ચતુષ્કોણનાં શિરોબિંદુઓ હોય, તો $x$ અને $y$ શોધો."),
    {0: ("विकर्ण परस्पर समद्विभाजित करते हैं: $(1, 2)$ और $(x, 6)$ का मध्य-बिंदु = $(4, y)$ और $(3, 5)$ का मध्य-बिंदु।", "વિકર્ણો પરસ્પર દુભાગે છે: $(1, 2)$ અને $(x, 6)$ નું મધ્યબિંદુ = $(4, y)$ અને $(3, 5)$ નું મધ્યબિંદુ.")})
add("ex7_2.q7", ("बिंदु A के निर्देशांक ज्ञात कीजिए, जहाँ AB एक वृत्त का व्यास है जिसका केंद्र $(2, -3)$ है तथा B के निर्देशांक $(1, 4)$ हैं।", "બિંદુ A ના યામ શોધો, જ્યાં AB એ વર્તુળનો વ્યાસ છે જેનું કેન્દ્ર $(2, -3)$ છે અને B ના યામ $(1, 4)$ છે."),
    {0: ("केंद्र $AB$ का मध्य-बिंदु है: $\\dfrac{x + 1}{2} = 2$ और $\\dfrac{y + 4}{2} = -3$।", "કેન્દ્ર $AB$ નું મધ્યબિંદુ છે: $\\dfrac{x + 1}{2} = 2$ અને $\\dfrac{y + 4}{2} = -3$.")})
add("ex7_2.q8", ("यदि A और B क्रमशः $(-2, -2)$ और $(2, -4)$ हैं, तो बिंदु P के निर्देशांक ज्ञात कीजिए ताकि $AP = \\dfrac{3}{7}AB$ हो और P रेखाखंड AB पर स्थित हो।", "જો A અને B અનુક્રમે $(-2, -2)$ અને $(2, -4)$ હોય, તો બિંદુ P ના યામ શોધો જેથી $AP = \\dfrac{3}{7}AB$ થાય અને P રેખાખંડ AB પર હોય."))
add("ex7_2.q9", ("बिंदुओं $A(-2, 2)$ और $B(2, 8)$ को मिलाने वाले रेखाखंड AB को चार बराबर भागों में विभाजित करने वाले बिंदुओं के निर्देशांक ज्ञात कीजिए।", "બિંદુઓ $A(-2, 2)$ અને $B(2, 8)$ ને જોડતા રેખાખંડ AB ને ચાર સરખા ભાગમાં વહેંચતાં બિંદુઓના યામ શોધો."),
    {0: ("बीच वाला बिंदु $AB$ का मध्य-बिंदु है: $(0, 5)$।", "વચ્ચેનું બિંદુ $AB$ નું મધ્યબિંદુ છે: $(0, 5)$."), 1: ("पहला बिंदु $A$ और $(0, 5)$ का मध्य-बिंदु है: $\\left(-1, \\dfrac{7}{2}\\right)$।", "પ્રથમ બિંદુ $A$ અને $(0, 5)$ નું મધ્યબિંદુ છે: $\\left(-1, \\dfrac{7}{2}\\right)$."),
     2: ("तीसरा बिंदु $(0, 5)$ और $B$ का मध्य-बिंदु है: $\\left(1, \\dfrac{13}{2}\\right)$।", "ત્રીજું બિંદુ $(0, 5)$ અને $B$ નું મધ્યબિંદુ છે: $\\left(1, \\dfrac{13}{2}\\right)$.")})
add("ex7_2.q10", ("एक समचतुर्भुज का क्षेत्रफल ज्ञात कीजिए, यदि इसके शीर्ष इसी क्रम में $(3, 0)$, $(4, 5)$, $(-1, 4)$ और $(-2, -1)$ हैं। [संकेत: समचतुर्भुज का क्षेत्रफल $= \\dfrac{1}{2}$(उसके विकर्णों का गुणनफल)]",
                  "જો સમબાજુ ચતુષ્કોણનાં શિરોબિંદુઓ આ ક્રમમાં $(3, 0)$, $(4, 5)$, $(-1, 4)$ અને $(-2, -1)$ હોય, તો તેનું ક્ષેત્રફળ શોધો. [સૂચન: સમબાજુ ચતુષ્કોણનું ક્ષેત્રફળ $= \\dfrac{1}{2}$(વિકર્ણોનો ગુણાકાર)]"),
    {0: ("विकर्ण 1: $(3, 0)$ से $(-1, 4)$: $\\sqrt{16 + 16} = 4\\sqrt{2}$।", "વિકર્ણ 1: $(3, 0)$ થી $(-1, 4)$: $\\sqrt{16 + 16} = 4\\sqrt{2}$."), 1: ("विकर्ण 2: $(4, 5)$ से $(-2, -1)$: $\\sqrt{36 + 36} = 6\\sqrt{2}$।", "વિકર્ણ 2: $(4, 5)$ થી $(-2, -1)$: $\\sqrt{36 + 36} = 6\\sqrt{2}$."),
     2: ("क्षेत्रफल $= \\dfrac{1}{2} \\times 4\\sqrt{2} \\times 6\\sqrt{2} = 24$ वर्ग इकाई", "ક્ષેત્રફળ $= \\dfrac{1}{2} \\times 4\\sqrt{2} \\times 6\\sqrt{2} = 24$ ચોરસ એકમ")})
# Examples
add("eg_triangle", ("क्या बिंदु $(3, 2)$, $(-2, -3)$ और $(2, 3)$ एक त्रिभुज बनाते हैं? यदि हाँ, तो उस त्रिभुज का प्रकार बताइए।", "શું બિંદુઓ $(3, 2)$, $(-2, -3)$ અને $(2, 3)$ ત્રિકોણ બનાવે છે? જો હા, તો તે ત્રિકોણનો પ્રકાર જણાવો."),
    {0: ("$PQ = \\sqrt{50}$, $QR = \\sqrt{52}$, $PR = \\sqrt{2}$: कोई दूरी अन्य दो के योग के बराबर नहीं, अतः वे त्रिभुज बनाते हैं।", "$PQ = \\sqrt{50}$, $QR = \\sqrt{52}$, $PR = \\sqrt{2}$: કોઈ અંતર બાકીના બેના સરવાળા જેટલું નથી, તેથી તે ત્રિકોણ બનાવે છે."),
     2: ("पाइथागोरस के विलोम से यह एक समकोण त्रिभुज है जिसका समकोण $P(3, 2)$ पर है।", "પાયથાગોરસના પ્રમેયના પ્રતીપ પરથી તે કાટકોણ ત્રિકોણ છે જેનો કાટખૂણો $P(3, 2)$ આગળ છે.")})
add("eg_yaxis", ("वह अनुपात ज्ञात कीजिए जिसमें $y$-अक्ष, बिंदुओं $(5, -6)$ और $(-1, -4)$ को मिलाने वाले रेखाखंड को विभाजित करता है। प्रतिच्छेद बिंदु भी ज्ञात कीजिए।", "$y$-અક્ષ બિંદુઓ $(5, -6)$ અને $(-1, -4)$ ને જોડતા રેખાખંડનું કયા ગુણોત્તરમાં વિભાજન કરે છે તે શોધો. છેદબિંદુ પણ શોધો."),
    {0: ("मान लीजिए अनुपात $k : 1$ है। $y$-अक्ष पर $x = 0$: $\\dfrac{-k + 5}{k + 1} = 0$, अतः $k = 5$।", "ધારો કે ગુણોત્તર $k : 1$ છે. $y$-અક્ષ પર $x = 0$: $\\dfrac{-k + 5}{k + 1} = 0$, તેથી $k = 5$."),
     1: ("अनुपात $5 : 1$ है।", "ગુણોત્તર $5 : 1$ છે."), 2: ("$y = \\dfrac{5 \\times (-4) + 1 \\times (-6)}{6} = -\\dfrac{13}{3}$: बिंदु $\\left(0, -\\dfrac{13}{3}\\right)$ है।", "$y = \\dfrac{5 \\times (-4) + 1 \\times (-6)}{6} = -\\dfrac{13}{3}$: બિંદુ $\\left(0, -\\dfrac{13}{3}\\right)$ છે.")})
add("eg_parallelogram", ("यदि बिंदु $A(6, 1)$, $B(8, 2)$, $C(9, 4)$ और $D(p, 3)$ इसी क्रम में एक समांतर चतुर्भुज के शीर्ष हैं, तो $p$ का मान ज्ञात कीजिए।", "જો બિંદુઓ $A(6, 1)$, $B(8, 2)$, $C(9, 4)$ અને $D(p, 3)$ આ ક્રમમાં સમાંતરબાજુ ચતુષ્કોણનાં શિરોબિંદુઓ હોય, તો $p$ ની કિંમત શોધો."),
    {0: ("$AC$ का मध्य-बिंदु = $BD$ का मध्य-बिंदु: $\\dfrac{15}{2} = \\dfrac{8 + p}{2}$", "$AC$ નું મધ્યબિંદુ = $BD$ નું મધ્યબિંદુ: $\\dfrac{15}{2} = \\dfrac{8 + p}{2}$")})
# Shine
add("vsa1", ("यदि $A\\left(\\dfrac{x}{2}, \\dfrac{y + 1}{2}\\right)$ और $B(x + 1, y - 3)$ को मिलाने वाले रेखाखंड का मध्य-बिंदु $C(5, -2)$ है, तो $x$ और $y$ ज्ञात कीजिए।", "જો $A\\left(\\dfrac{x}{2}, \\dfrac{y + 1}{2}\\right)$ અને $B(x + 1, y - 3)$ ને જોડતા રેખાખંડનું મધ્યબિંદુ $C(5, -2)$ હોય, તો $x$ અને $y$ શોધો."))
add("vsa2", ("$y$-अक्ष पर वह बिंदु ज्ञात कीजिए जो $(-5, -2)$ और $(3, 2)$ से समदूरस्थ है।", "$y$-અક્ષ પરનું એવું બિંદુ શોધો જે $(-5, -2)$ અને $(3, 2)$ થી સમાન અંતરે હોય."),
    {0: ("मान लीजिए बिंदु $(0, y)$ है: $25 + (y + 2)^{2} = 9 + (y - 2)^{2}$, अतः $8y = -16$।", "ધારો કે બિંદુ $(0, y)$ છે: $25 + (y + 2)^{2} = 9 + (y - 2)^{2}$, તેથી $8y = -16$."),
     1: ("$y = -2$: बिंदु $(0, -2)$ है।", "$y = -2$: બિંદુ $(0, -2)$ છે.")})
add("sa1", ("दर्शाइए कि बिंदु $(1, 7)$, $(4, 2)$, $(-1, -1)$ और $(-4, 4)$ एक वर्ग के शीर्ष हैं।", "બતાવો કે બિંદુઓ $(1, 7)$, $(4, 2)$, $(-1, -1)$ અને $(-4, 4)$ ચોરસનાં શિરોબિંદુઓ છે."),
    {0: ("चारों भुजाएँ $\\sqrt{9 + 25} = \\sqrt{34}$ हैं।", "ચારેય બાજુઓ $\\sqrt{9 + 25} = \\sqrt{34}$ છે."), 1: ("विकर्ण: $\\sqrt{4 + 64} = \\sqrt{68}$ और $\\sqrt{64 + 4} = \\sqrt{68}$।", "વિકર્ણો: $\\sqrt{4 + 64} = \\sqrt{68}$ અને $\\sqrt{64 + 4} = \\sqrt{68}$."),
     2: ("बराबर भुजाएँ और बराबर विकर्ण, अतः यह एक वर्ग है।", "સરખી બાજુઓ અને સરખા વિકર્ણો, તેથી તે ચોરસ છે.")})
add("sa2", ("यदि $A(-2, 1)$, $B(a, 0)$, $C(4, b)$ और $D(1, 2)$ समांतर चतुर्भुज $ABCD$ के शीर्ष हैं, तो $a$ और $b$ के मान ज्ञात कीजिए।", "જો $A(-2, 1)$, $B(a, 0)$, $C(4, b)$ અને $D(1, 2)$ સમાંતરબાજુ ચતુષ્કોણ $ABCD$ નાં શિરોબિંદુઓ હોય, તો $a$ અને $b$ ની કિંમતો શોધો."),
    {0: ("विकर्ण परस्पर समद्विभाजित करते हैं: $AC$ का मध्य-बिंदु = $BD$ का मध्य-बिंदु।", "વિકર્ણો પરસ્પર દુભાગે છે: $AC$ નું મધ્યબિંદુ = $BD$ નું મધ્યબિંદુ.")})
add("sa3", ("यदि बिंदु $P(9a - 2, -b)$, $A(3a + 1, -3)$ और $B(8a, 5)$ को मिलाने वाले रेखाखंड को $3 : 1$ के अनुपात में विभाजित करता है, तो $a$ और $b$ के मान ज्ञात कीजिए।", "જો બિંદુ $P(9a - 2, -b)$ એ $A(3a + 1, -3)$ અને $B(8a, 5)$ ને જોડતા રેખાખંડનું $3 : 1$ ગુણોત્તરમાં વિભાજન કરે, તો $a$ અને $b$ ની કિંમતો શોધો."),
    {0: ("$x$: $\\dfrac{3 \\times 8a + 1 \\times (3a + 1)}{4} = 9a - 2$, अर्थात् $27a + 1 = 36a - 8$, अतः $a = 1$।", "$x$: $\\dfrac{3 \\times 8a + 1 \\times (3a + 1)}{4} = 9a - 2$, એટલે કે $27a + 1 = 36a - 8$, તેથી $a = 1$.")})
add("sa4", ("सिद्ध कीजिए कि बिंदु $(3, 0)$, $(6, 4)$ और $(-1, 3)$ एक समकोण समद्विबाहु त्रिभुज के शीर्ष हैं।", "સાબિત કરો કે બિંદુઓ $(3, 0)$, $(6, 4)$ અને $(-1, 3)$ કાટકોણ સમદ્વિબાજુ ત્રિકોણનાં શિરોબિંદુઓ છે."),
    {1: ("$AB = AC$, अतः त्रिभुज समद्विबाहु है।", "$AB = AC$, તેથી ત્રિકોણ સમદ્વિબાજુ છે."), 2: ("$AB^{2} + AC^{2} = 25 + 25 = 50 = BC^{2}$, अतः $A$ पर कोण $90^\\circ$ है।", "$AB^{2} + AC^{2} = 25 + 25 = 50 = BC^{2}$, તેથી $A$ આગળનો ખૂણો $90^\\circ$ છે.")})
add("la1", ("$\\triangle ABC$ के शीर्ष $A(4, 6)$, $B(1, 5)$ और $C(7, 2)$ हैं। भुजाओं $AB$ और $AC$ को क्रमशः $D$ और $E$ पर प्रतिच्छेद करती एक रेखा इस प्रकार खींची गई है कि $\\dfrac{AD}{AB} = \\dfrac{AE}{AC} = \\dfrac{1}{4}$ है। $D$ और $E$ के निर्देशांक ज्ञात कीजिए और दर्शाइए कि $DE = \\dfrac{1}{4}BC$ है।",
             "$\\triangle ABC$ નાં શિરોબિંદુઓ $A(4, 6)$, $B(1, 5)$ અને $C(7, 2)$ છે. બાજુઓ $AB$ અને $AC$ ને અનુક્રમે $D$ અને $E$ માં છેદતી રેખા એવી રીતે દોરી છે કે $\\dfrac{AD}{AB} = \\dfrac{AE}{AC} = \\dfrac{1}{4}$. $D$ અને $E$ ના યામ શોધો અને બતાવો કે $DE = \\dfrac{1}{4}BC$."),
    {0: ("$\\dfrac{AD}{AB} = \\dfrac{1}{4}$ का अर्थ है $AD : DB = 1 : 3$, और इसी प्रकार $AE : EC = 1 : 3$।", "$\\dfrac{AD}{AB} = \\dfrac{1}{4}$ નો અર્થ છે $AD : DB = 1 : 3$, અને તે જ રીતે $AE : EC = 1 : 3$."),
     4: ("$BC = \\sqrt{36 + 9} = 3\\sqrt{5}$, अतः $DE = \\dfrac{1}{4}BC$।", "$BC = \\sqrt{36 + 9} = 3\\sqrt{5}$, તેથી $DE = \\dfrac{1}{4}BC$.")})
add("la2", ("$P$ और $Q$, $A(2, 1)$ और $B(5, -8)$ को मिलाने वाले रेखाखंड के सम-त्रिभाजन बिंदु हैं, जिनमें $P$, $A$ के निकट है। (i) $P$ और $Q$ ज्ञात कीजिए। (ii) यदि $P$ रेखा $2x - y + k = 0$ पर स्थित है, तो $k$ ज्ञात कीजिए। (iii) दर्शाइए कि $AP = PQ = QB$।",
             "$P$ અને $Q$ એ $A(2, 1)$ અને $B(5, -8)$ ને જોડતા રેખાખંડનાં ત્રિભાજન બિંદુઓ છે, જેમાં $P$ એ $A$ ની નજીક છે. (i) $P$ અને $Q$ શોધો. (ii) જો $P$ રેખા $2x - y + k = 0$ પર હોય, તો $k$ શોધો. (iii) બતાવો કે $AP = PQ = QB$."),
    {0: ("(i) $P$, $AB$ को $1 : 2$ में विभाजित करता है: $P = \\left(\\dfrac{5 + 4}{3}, \\dfrac{-8 + 2}{3}\\right) = (3, -2)$।", "(i) $P$ એ $AB$ નું $1 : 2$ માં વિભાજન કરે છે: $P = \\left(\\dfrac{5 + 4}{3}, \\dfrac{-8 + 2}{3}\\right) = (3, -2)$."),
     1: ("$Q$, $AB$ को $2 : 1$ में विभाजित करता है: $Q = \\left(\\dfrac{10 + 2}{3}, \\dfrac{-16 + 1}{3}\\right) = (4, -5)$।", "$Q$ એ $AB$ નું $2 : 1$ માં વિભાજન કરે છે: $Q = \\left(\\dfrac{10 + 2}{3}, \\dfrac{-16 + 1}{3}\\right) = (4, -5)$."),
     2: ("(ii) $2 \\times 3 - (-2) + k = 0$, अतः $k = -8$।", "(ii) $2 \\times 3 - (-2) + k = 0$, તેથી $k = -8$."),
     3: ("(iii) $AP = \\sqrt{1 + 9} = \\sqrt{10}$, $PQ = \\sqrt{1 + 9} = \\sqrt{10}$, $QB = \\sqrt{1 + 9} = \\sqrt{10}$।", "(iii) $AP = \\sqrt{1 + 9} = \\sqrt{10}$, $PQ = \\sqrt{1 + 9} = \\sqrt{10}$, $QB = \\sqrt{1 + 9} = \\sqrt{10}$."),
     4: ("अतः $AP = PQ = QB$।", "તેથી $AP = PQ = QB$.")})
add("sqp37", ("कक्षा X के विद्यार्थियों का एक समूह सर्दी की छुट्टियों में पिकनिक पर जाता है। तीन मित्रों अमन, कीर्ति और चाहत की स्थितियाँ बिंदुओं $P(2, 5)$, $Q(4, 4)$ और $R(8, 3)$ द्वारा दर्शाई गई हैं।\n\n(i) P और R के बीच की दूरी ज्ञात कीजिए। (1)\n\n(ii) क्या Q, PR का मध्य-बिंदु है? PR का मध्य-बिंदु ज्ञात करके कारण दीजिए। (1)\n\n(iii) $x$-अक्ष पर वह बिंदु ज्ञात कीजिए जो P और Q से समदूरस्थ है। अथवा मान लीजिए S एक बिंदु है जो PQ को मिलाने वाली रेखा को $2 : 3$ के अनुपात में विभाजित करता है। S के निर्देशांक ज्ञात कीजिए। (2)",
               "ધોરણ X ના વિદ્યાર્થીઓનું એક જૂથ શિયાળાના વેકેશનમાં પિકનિકે જાય છે. ત્રણ મિત્રો અમન, કીર્તિ અને ચાહતનાં સ્થાન બિંદુઓ $P(2, 5)$, $Q(4, 4)$ અને $R(8, 3)$ વડે દર્શાવ્યાં છે.\n\n(i) P અને R વચ્ચેનું અંતર શોધો. (1)\n\n(ii) શું Q એ PR નું મધ્યબિંદુ છે? PR નું મધ્યબિંદુ શોધીને કારણ આપો. (1)\n\n(iii) $x$-અક્ષ પરનું એવું બિંદુ શોધો જે P અને Q થી સમાન અંતરે હોય. અથવા ધારો કે S એ PQ ને જોડતી રેખાનું $2 : 3$ ગુણોત્તરમાં વિભાજન કરતું બિંદુ છે. S ના યામ શોધો. (2)"),
    {1: ("(ii) PR का मध्य-बिंदु $= \\left(\\dfrac{2 + 8}{2}, \\dfrac{5 + 3}{2}\\right) = (5, 4) \\neq Q(4, 4)$, अतः Q मध्य-बिंदु नहीं है।", "(ii) PR નું મધ્યબિંદુ $= \\left(\\dfrac{2 + 8}{2}, \\dfrac{5 + 3}{2}\\right) = (5, 4) \\neq Q(4, 4)$, તેથી Q મધ્યબિંદુ નથી."),
     2: ("(iii) $(x - 2)^{2} + 25 = (x - 4)^{2} + 16$ से $4x = 3$: बिंदु $\\left(\\dfrac{3}{4}, 0\\right)$ है। अथवा $S = \\left(\\dfrac{2 \\times 4 + 3 \\times 2}{5}, \\dfrac{2 \\times 4 + 3 \\times 5}{5}\\right) = \\left(\\dfrac{14}{5}, \\dfrac{23}{5}\\right)$",
         "(iii) $(x - 2)^{2} + 25 = (x - 4)^{2} + 16$ પરથી $4x = 3$: બિંદુ $\\left(\\dfrac{3}{4}, 0\\right)$ છે. અથવા $S = \\left(\\dfrac{2 \\times 4 + 3 \\times 2}{5}, \\dfrac{2 \\times 4 + 3 \\times 5}{5}\\right) = \\left(\\dfrac{14}{5}, \\dfrac{23}{5}\\right)$")})
Q["ch07.q.sqp37.figure.title"] = ("अमन (P), कीर्ति (Q) और चाहत (R)", "અમન (P), કીર્તિ (Q) અને ચાહત (R)")
add("cb2", ("एक शहर के नक्शे पर स्कूल $S(2, 3)$ पर और अस्पताल $H(8, 11)$ पर है, जहाँ 1 इकाई $= 1$ km है।\n\n(i) अस्पताल स्कूल से कितनी दूर है? (1)\n\n(ii) एक पुस्तकालय ठीक इनके बीच में है। उसकी स्थिति ज्ञात कीजिए। (1)\n\n(iii) एक बस स्टॉप $SH$ को $1 : 3$ के अनुपात में विभाजित करता है। उसकी स्थिति ज्ञात कीजिए। अथवा $x$-अक्ष पर $S$ और $H$ से समदूरस्थ बिंदु ज्ञात कीजिए। (2)",
             "એક શહેરના નકશા પર શાળા $S(2, 3)$ પર અને હોસ્પિટલ $H(8, 11)$ પર છે, જ્યાં 1 એકમ $= 1$ km છે.\n\n(i) હોસ્પિટલ શાળાથી કેટલી દૂર છે? (1)\n\n(ii) એક પુસ્તકાલય બરાબર તેમની વચ્ચે છે. તેનું સ્થાન શોધો. (1)\n\n(iii) એક બસ સ્ટોપ $SH$ નું $1 : 3$ ગુણોત્તરમાં વિભાજન કરે છે. તેનું સ્થાન શોધો. અથવા $x$-અક્ષ પર $S$ અને $H$ થી સમાન અંતરે આવેલું બિંદુ શોધો. (2)"),
    {1: ("(ii) मध्य-बिंदु $= \\left(\\dfrac{2 + 8}{2}, \\dfrac{3 + 11}{2}\\right) = (5, 7)$", "(ii) મધ્યબિંદુ $= \\left(\\dfrac{2 + 8}{2}, \\dfrac{3 + 11}{2}\\right) = (5, 7)$"),
     2: ("(iii) $\\left(\\dfrac{1 \\times 8 + 3 \\times 2}{4}, \\dfrac{1 \\times 11 + 3 \\times 3}{4}\\right) = \\left(\\dfrac{7}{2}, 5\\right)$। अथवा $(x - 2)^{2} + 9 = (x - 8)^{2} + 121$ से $12x = 172$: बिंदु $\\left(\\dfrac{43}{3}, 0\\right)$ है।",
         "(iii) $\\left(\\dfrac{1 \\times 8 + 3 \\times 2}{4}, \\dfrac{1 \\times 11 + 3 \\times 3}{4}\\right) = \\left(\\dfrac{7}{2}, 5\\right)$. અથવા $(x - 2)^{2} + 9 = (x - 8)^{2} + 121$ પરથી $12x = 172$: બિંદુ $\\left(\\dfrac{43}{3}, 0\\right)$ છે.")})

